# No match with 8 hex characters. Let's try different lengths and character sets
import itertools

prime = 0x1000193
prime_inv = 0x359c449b
initial = 0x811c9dc5
target = 0xcfb2ee18

def fnv1a_partial(data, h=0x811c9dc5):
    for b in data:
        h = ((h ^ b) * prime) & 0xFFFFFFFF
    return h

def fnv1a_reverse(data, final):
    h = final
    for b in reversed(data):
        h = ((h * prime_inv) & 0xFFFFFFFF) ^ b
    return h

# Try alphanumeric with meet-in-the-middle for lengths 6, 7, 8
alnum = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

# Try 3+3 = 6
print("Trying 3+3 alphanumeric...")
forward_table = {}
for combo in itertools.product(alnum, repeat=3):
    prefix = ''.join(combo).encode()
    h = fnv1a_partial(prefix, initial)
    forward_table[h] = prefix

for combo in itertools.product(alnum, repeat=3):
    suffix = ''.join(combo).encode()
    h = fnv1a_reverse(suffix, target)
    if h in forward_table:
        prefix = forward_table[h]
        full = prefix + suffix
        if fnv1a_partial(full, initial) == target:
            print(f"FOUND: '{full.decode()}'")

# Try 4+3 = 7
print("Trying 4+3 alphanumeric...")
forward_table = {}
for combo in itertools.product(alnum, repeat=4):
    prefix = ''.join(combo).encode()
    h = fnv1a_partial(prefix, initial)
    forward_table[h] = prefix

for combo in itertools.product(alnum, repeat=3):
