    h = fnv1a_reverse(suffix, target)
    if h in forward_table:
        prefix = forward_table[h]
        full = prefix + suffix
        if fnv1a_partial(full, initial) == target:
            print(f"FOUND: '{full.decode()}'")

# Try 3+4 = 7
print("Trying 3+4 alphanumeric...")
forward_table = {}
for combo in itertools.product(alnum, repeat=3):
    prefix = ''.join(combo).encode()
    h = fnv1a_partial(prefix, initial)
    forward_table[h] = prefix

for combo in itertools.product(alnum, repeat=4):
    suffix = ''.join(combo).encode()
    h = fnv1a_reverse(suffix, target)
    if h in forward_table:
        prefix = forward_table[h]
        full = prefix + suffix
        if fnv1a_partial(full, initial) == target:
            print(f"FOUND: '{full.decode()}'")

print("Done")
